# [doc = " Create a `TimeZone` value from TZif data in a file at compile time."] # [doc = ""] # [doc = " This reads the data in the file path given, parses it as TZif specified by"] # [doc = " [RFC 9636], and constructs a `TimeZone` value for use in a `const` context."] # [doc = " This enables using IANA time zones with Jiff in core-only environments. No"] # [doc = " dynamic memory allocation is used."] # [doc = ""] # [doc = " Unlike [`jiff::tz::get`](get), this reads TZif data from a file."] # [doc = " `jiff::tz::get`, in contrast, reads TZif data from the [`jiff-tzdb`] crate."] # [doc = " `jiff::tz::get` is more convenient and doesn't require managing your own"] # [doc = " TZif files, but it comes at the cost of a compile-time dependency on"] # [doc = " `jiff-tzdb` and being forced to use whatever data is in `jiff-tzdb`."] # [doc = ""] # [doc = " # Input"] # [doc = ""] # [doc = " This macro takes two positional parameters that must be literal strings."] # [doc = ""] # [doc = " The first is required and is a path to a file containing TZif data. For"] # [doc = " example, `/usr/share/zoneinfo/America/New_York`."] # [doc = ""] # [doc = " The second parameter is an IANA time zone identifier, e.g.,"] # [doc = " `America/New_York`, and is required only when an IANA time zone identifier"] # [doc = " could not be determined from the file path. The macro will automatically"] # [doc = " infer an IANA time zone identifier as anything after the last occurrence"] # [doc = " of the literal `zoneinfo/` in the file path."] # [doc = ""] # [doc = " # Return type"] # [doc = ""] # [doc = " This macro returns a value with type `TimeZone`. To get a `&'static"] # [doc = " TimeZone`, simply use `&include!(\"...\")`."] # [doc = ""] # [doc = " # Usage"] # [doc = ""] # [doc = " Callers should only call this macro once for each unique IANA time zone"] # [doc = " identifier you need. Otherwise, multiple copies of the same embedded"] # [doc = " time zone data could appear in your binary. There are no correctness"] # [doc = " issues with this, but it could make your binary bigger than it needs to be."] # [doc = ""] # [doc = " # When should I use this?"] # [doc = ""] # [doc = " Users should only use this macro if they have a _specific need_ for it"] # [doc = " (like using a time zone on an embedded device). In particular, this will"] # [doc = " embed the time zone transition rules into your binary. If the time zone"] # [doc = " rules change, your program will need to be re-compiled."] # [doc = ""] # [doc = " In contrast, Jiff's default configuration on Unix is to read from"] # [doc = " `/usr/share/zoneinfo` at runtime. This means your application will"] # [doc = " automatically use time zone updates and doesn't need to be re-compiled."] # [doc = ""] # [doc = " Using a static `TimeZone` may also be faster in some cases. In particular,"] # [doc = " a `TimeZone` created at runtime from a `/usr/share/zoneinfo` uses"] # [doc = " automatic reference counting internally. In contrast, a `TimeZone` created"] # [doc = " with this macro does not."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to find the next DST transition from a particular"] # [doc = " timestamp in `Europe/Zurich`, and then print that in local time for Zurich:"] # [doc = ""] # [doc = " ```ignore"] # [doc = " use jiff::{tz::{self, TimeZone}, Timestamp};"] # [doc = ""] # [doc = " static TZ: TimeZone = tz::include!(\"/usr/share/zoneinfo/Europe/Zurich\");"] # [doc = ""] # [doc = " let ts: Timestamp = \"2025-02-25T00:00Z\".parse()?;"] # [doc = " let Some(next_transition) = TZ.following(ts).next() else {"] # [doc = "     return Err(\"no time zone transitions\".into());"] # [doc = " };"] # [doc = " let zdt = next_transition.timestamp().to_zoned(TZ.clone());"] # [doc = " assert_eq!(zdt.to_string(), \"2025-03-30T03:00:00+02:00[Europe/Zurich]\");"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: using `/etc/localtime`"] # [doc = ""] # [doc = " On most Unix systems, `/etc/localtime` is a symbolic link to a file in"] # [doc = " your `/usr/share/zoneinfo` directory. This means it is a valid input to"] # [doc = " this macro. However, Jiff currently does not detect the IANA time zone"] # [doc = " identifier, so you'll need to provide it yourself:"] # [doc = ""] # [doc = " ```ignore"] # [doc = " use jiff::{tz::{self, TimeZone}, Timestamp};"] # [doc = ""] # [doc = " static TZ: TimeZone = tz::include!(\"/etc/localtime\", \"America/New_York\");"] # [doc = ""] # [doc = " let ts: Timestamp = \"2025-02-25T00:00Z\".parse()?;"] # [doc = " let zdt = ts.to_zoned(TZ.clone());"] # [doc = " assert_eq!(zdt.to_string(), \"2025-02-24T19:00:00-05:00[America/New_York]\");"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Note that this is reading `/etc/localtime` _at compile time_, which means"] # [doc = " that the program will only use the time zone on the system in which it"] # [doc = " was compiled. It will _not_ use the time zone of the system running it."] # [doc = ""] # [doc = " [RFC 9636]: https://datatracker.ietf.org/doc/rfc9636/"] # [doc = " [`jiff-tzdb`]: https://docs.rs/jiff-tzdb"] # [cfg (feature = "static-tz")] pub use jiff_static :: include ;
